			mieDirectionalG: { value: .8 },
			sunPosition: { value: new Vector3(0, 1, 0) },
			moonPosition: { value: new Vector3(0, -1, 0) },
			time: { value: 0 },
			cloudCoverage: { value: .3 },
			cloudDensity: { value: .5 },
			cloudSoftness: { value: .3 },
			cloudDarkness: { value: 0 },
			cloudOffset: { value: new Vector2() },
			overcast: { value: 0 },
			night: { value: 0 },
			horizonFog: { value: 0 },
			horizonColor: { value: new Color() },
			deckColor: { value: new Color(1, 1, 1) },
			flash: { value: 0 },
			flashDirection: { value: new Vector3(0, 1, 0) },
