		const base = env.wind_strength;
		const s = this.time;
		const gustNoise = Math.sin(s * .31) * .5 + Math.sin(s * .77 + 1.3) * .3 + Math.sin(s * 1.9 + 4.1) * .2;
		const gust = Math.max(0, gustNoise) * (.25 + storm * .6 + this.rain * .15);
		this.windNow = base * (1 + gust) + storm * .25 * Math.max(0, gustNoise);
		const aw = this.atmosphere.wind;
		const len = aw.length();
		if (len > 1e-4) this.windDir.set(aw.x / len, aw.y / len);
		this.windVec.copy(this.windDir).multiplyScalar(this.windNow);
		this.world.setFoliageWind?.(this.windNow);
		const wet = MathUtils.clamp(Math.max(this.envWetness, this.soaked * .9) * (1 - this.snowCover * .6), 0, 1);
		this.world.material.setWeather(wet, this.snowCover);
		this.world.water.setWeather(this.rain, this.windNow, this.windDir.x, this.windDir.y);
		camera.getWorldPosition(this.camPos);
		const underwater = this.atmosphere.isUnderwater;
		this.atmosphere.ambientColor(this.light);
		this.light.addScalar(this.atmosphere.flash * .6);
		this.precipitation.update(dt, camera, this.rain, this.snow, this.windVec, this.light, underwater);
		this.updateLightning(dt);
