/**
* Colour grading in scene-linear HDR (before tone mapping, like UE's post-process volume):
* contrast in log space around 18% grey, saturation around luminance, vignette, and an
* optional neighbourhood-clamped unsharp mask (CAS-like, no halos).
*/
var GradingShader = {
	name: "WaterwaysGradingShader",
	defines: { SHARPEN: 0 },
	uniforms: {
		tDiffuse: { value: null },
		texel: { value: new Vector2(1, 1) },
		aspect: { value: 1 },
		saturation: { value: 1 },
		contrast: { value: 1 },
		vignette: { value: 0 },
		sharpen: { value: 0 }
	},
	vertexShader: `
        varying vec2 vUv;
        void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }`,
	fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform vec2 texel;
        uniform float aspect;
        uniform float saturation;
        uniform float contrast;
        uniform float vignette;
        uniform float sharpen;
        varying vec2 vUv;

        void main() {
            vec4 base = texture2D(tDiffuse, vUv);
            vec3 col = base.rgb;

            #if SHARPEN
                vec3 n = texture2D(tDiffuse, vUv + vec2(0.0, texel.y)).rgb;
                vec3 s = texture2D(tDiffuse, vUv - vec2(0.0, texel.y)).rgb;
                vec3 e = texture2D(tDiffuse, vUv + vec2(texel.x, 0.0)).rgb;
                vec3 w = texture2D(tDiffuse, vUv - vec2(texel.x, 0.0)).rgb;
                vec3 lo = min(col, min(min(n, s), min(e, w)));
                vec3 hi = max(col, max(max(n, s), max(e, w)));
                vec3 blur = (n + s + e + w) * 0.25;
                col = clamp(col + (col - blur) * sharpen * 2.5, lo, hi);
            #endif

            float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
            col = max(mix(vec3(luma), col, saturation), 0.0);
            col = 0.18 * pow(col / 0.18 + 1e-5, vec3(contrast));

            vec2 d = (vUv - 0.5) * vec2(aspect, 1.0);
            float r = length(d) / length(vec2(aspect, 1.0) * 0.5);
            col *= 1.0 - vignette * 0.85 * smoothstep(0.3, 1.0, r);

            gl_FragColor = vec4(col, base.a);
        }`
};
function gradingActive(g) {
	return (g.sharpen ?? 0) > .001 || (g.vignette ?? 0) > .001 || Math.abs((g.saturation ?? 1) - 1) > .001 || Math.abs((g.contrast ?? 1) - 1) > .001;
}
/**
* Post-processing chain: Render → GTAO → Bloom → Grading → Output (tone map + sRGB) → FXAA / SMAA.
*
* FXAA and SMAA run last because both expect display-referred (tone mapped, sRGB) input. MSAA is a
* multisampled scene target instead. Passes that would be no-ops are left out; the composer is only
* rebuilt when that structure changes, everything else updates uniforms.
*
* The composer can render below the canvas resolution (dynamic resolution): the final pass draws to the
* full-size canvas and upscales with bilinear filtering.
*/
var PostFx = class {
	renderer;
	scene;
	camera;
	composer;
	structure = "";
	aoPass = null;
	bloomPass = null;
	gradePass = null;
	msaa = false;
	width = 1;
	height = 1;
	pixelRatio = 1;
	renderSize = new Vector2(1, 1);
	constructor(renderer, scene, camera) {
		this.renderer = renderer;
		this.scene = scene;
		this.camera = camera;
		this.composer = new EffectComposer(renderer);
	}
	/** Human readable list of the active passes (debugging / stats). */
	get passNames() {
		return this.composer.passes.map((p) => p instanceof RenderPass ? "Scene" : p instanceof GTAOPass ? "GTAO" : p instanceof UnrealBloomPass ? "Bloom" : p instanceof FXAAPass ? "FXAA" : p instanceof SMAAPass ? "SMAA" : p instanceof OutputPass ? "Output" : p === this.gradePass ? "Grade" : "Pass").concat(this.msaa ? ["(MSAA 4×)"] : []);
	}
	configure(g) {
		const aa = antiAliasingMode(g);
		const bloom = g.bloom && (g.bloom_intensity ?? .12) > .001;
		const structure = [
			aa,
			g.ambient_occlusion ? "ao" : "-",
			bloom ? "bloom" : "-",
			gradingActive(g) ? "grade" : "-"
		].join("|");
		if (structure !== this.structure) {
			this.structure = structure;
			this.build(aa, g.ambient_occlusion, bloom, gradingActive(g));
		}
		this.updateUniforms(g);
	}
	setSize(width, height, pixelRatio) {
		this.width = width;
		this.height = height;
		this.pixelRatio = pixelRatio;
		this.composer.setPixelRatio(pixelRatio);
		this.composer.setSize(width, height);
		this.renderSize.set(Math.max(1, Math.floor(width * pixelRatio)), Math.max(1, Math.floor(height * pixelRatio)));
		this.updateGradeSize();
	}
	render(dt) {
		this.composer.render(dt);
	}
	dispose() {
		this.disposePasses();
		this.composer.dispose();
	}
	build(aa, ao, bloom, grade) {
		this.disposePasses();
		this.composer.dispose();
		const w = Math.max(1, Math.floor(this.width * this.pixelRatio));
		const h = Math.max(1, Math.floor(this.height * this.pixelRatio));
		const target = new WebGLRenderTarget(w, h, {
			type: HalfFloatType,
			samples: aa === "msaa" ? 4 : 0
		});
		const composer = new EffectComposer(this.renderer, target);
		composer.setPixelRatio(this.pixelRatio);
		composer.setSize(this.width, this.height);
		composer.addPass(new RenderPass(this.scene, this.camera));
		this.aoPass = null;
		this.bloomPass = null;
		this.gradePass = null;
		if (ao) {
			this.aoPass = new ScaledGTAOPass(this.scene, this.camera, w, h);
			this.aoPass.blendIntensity = .8;
			composer.addPass(this.aoPass);
		}
		if (bloom) {
			this.bloomPass = new UnrealBloomPass(new Vector2(w, h), .12, .45, 3.5);
			composer.addPass(this.bloomPass);
		}
		if (grade) {
			this.gradePass = new ShaderPass(GradingShader);
			composer.addPass(this.gradePass);
		}
		composer.addPass(new OutputPass());
		if (aa === "fxaa") composer.addPass(new FXAAPass());
		else if (aa === "smaa") composer.addPass(new SMAAPass());
		this.composer = composer;
		this.msaa = aa === "msaa";
		this.updateGradeSize();
	}
	updateUniforms(g) {
		if (this.aoPass) {
			const q = AO_QUALITY[g.ao_quality ?? "medium"] ?? AO_QUALITY.medium;
			this.aoPass.setResolutionScale(q.scale);
			this.aoPass.updateGtaoMaterial({
				radius: q.radius,
				distanceExponent: 1.5,
				thickness: 2,
				scale: 1,
				samples: q.samples
			});
			this.aoPass.updatePdMaterial({ samples: q.pdSamples });
		}
		if (this.bloomPass) this.bloomPass.strength = g.bloom_intensity ?? .12;
		if (this.gradePass) {
			const u = this.gradePass.uniforms;
			u.saturation.value = g.saturation ?? 1;
			u.contrast.value = g.contrast ?? 1;
			u.vignette.value = g.vignette ?? 0;
			u.sharpen.value = g.sharpen ?? 0;
			const sharpen = (g.sharpen ?? 0) > .001 ? 1 : 0;
			const material = this.gradePass.material;
			if (material.defines.SHARPEN !== sharpen) {
				material.defines.SHARPEN = sharpen;
				material.needsUpdate = true;
			}
		}
	}
	updateGradeSize() {
		if (!this.gradePass) return;
		const u = this.gradePass.uniforms;
		u.texel.value.set(1 / this.renderSize.x, 1 / this.renderSize.y);
		u.aspect.value = this.renderSize.x / this.renderSize.y;
	}
	disposePasses() {
		for (const pass of this.composer.passes) pass.dispose();
	}
};
